import json,urllib.request,urllib.error,urllib.parse
out={}
for label,path in [('root','/'),('login','/login'),('register','/register')]:
 try:
  req=urllib.request.Request('https://app.ontrackegy.com'+path,headers={'User-Agent':'OnTrack-Postdeploy-Smoke/1.0'})
  with urllib.request.urlopen(req,timeout=6) as response:
   out[label]={'status':response.status,'final_path':urllib.parse.urlparse(response.url).path}
 except urllib.error.HTTPError as e:
  out[label]={'status':e.code,'final_path':path}
 except Exception as e:
  out[label]={'error':type(e).__name__}
print(json.dumps(out))
if any(v.get('status',0)>=500 for v in out.values()):raise SystemExit(1)
